-- Órganos de Gobierno pasa a la relación de la Junta (maqueta B): el texto de
-- entrada en formato carta y, debajo, un cargo por fila con quién lo ocupa y
-- qué hace; las vocalías enlazan a su página. Los nombres, el mandato y la
-- fecha del cabildo quedan vacíos hasta que el Grupo los dé: la web pinta el
-- cargo y su función. Sin tarjetas ni iconos.
--
-- Solo se sustituye la página que sigue con el texto de partida: si alguien ya
-- la ha editado en el CMS, se queda como está.

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Órganos de Gobierno","subtitulo":"Junta de Gobierno y órganos de dirección de la corporación.","foto":"","fotoAlt":""},"bloques":[{"tipo":"texto","titulo":"","html":"<p>La Junta de Gobierno es el órgano colegiado encargado de la dirección, administración y representación del Grupo Parroquial. Desde sus distintas vocalías, trabaja unida al servicio de los hermanos y de la misión evangelizadora de la corporación.</p><p>Gobernar un grupo parroquial es, sobre todo, servir: cada cargo es una tarea que alguien asume por amor a la Virgen y a sus hermanos, en comunión con la parroquia.</p>","presentacion":{"estilo":"carta"}},{"tipo":"relacion","titulo":"Junta de Gobierno","mandato":"","nota":"","filas":[{"cargo":"Hermano Mayor","nombre":"","texto":"Representa al Grupo Parroquial y dirige su vida con la Junta.","enlace":""},{"cargo":"Teniente Hermano Mayor","nombre":"","texto":"Asiste al Hermano Mayor y le sustituye en su ausencia.","enlace":""},{"cargo":"Secretaría","nombre":"","texto":"Actas, correspondencia oficial y archivo de la corporación.","enlace":""},{"cargo":"Tesorería","nombre":"","texto":"Administra los bienes del Grupo Parroquial, con transparencia.","enlace":""},{"cargo":"Vocalía de Cultos","nombre":"","texto":"Los cultos y las celebraciones en honor de la Titular","enlace":"/cultos"},{"cargo":"Vocalía de Caridad","nombre":"","texto":"La ayuda a quien la necesita","enlace":"/nuestros-fines/caridad"},{"cargo":"Vocalía de Formación","nombre":"","texto":"Crecer en la fe","enlace":"/nuestros-fines/formacion"}]},{"tipo":"cita","titulo":"","presentacion":{"estilo":"franja","alineacion":"centro"},"texto":"El que quiera ser grande entre vosotros, que sea vuestro servidor.","autor":"Jesús","fuente":"Evangelio según san Mateo, 20, 26"},{"tipo":"llamada","titulo":"","texto":"¿Quieres hacer llegar algo a la Junta de Gobierno?","boton":"Escribir a la Junta","enlace":"/contacto"}]}'
WHERE `slug` = 'organos-de-gobierno' AND `datos` LIKE '%Cargos de la Junta de Gobierno%' AND `datos` LIKE '%"tipo":"tarjetas"%';
